import os, glob, openpyxl, docx

base = "/filesystem/dc_structural__eor_revision__blind/project"

for f in sorted(glob.glob(base + "/contract/*") + glob.glob(base + "/index/*.csv") + glob.glob(base + "/review/*.csv") + glob.glob(base + "/review/*.xml") + glob.glob(base + "/review/other_discipline/*.csv")):
