import pymupdf, glob, os, re

base = "/filesystem/dc_structural__eor_revision__blind/project/drawings"
for sub in ["bp2_current", "bp3_current", "superseded"]:
    for f in sorted(glob.glob(f"{base}/{sub}/*.pdf")):
        doc = pymupdf.open(f)
        ocgs = {k: v["name"] for k, v in doc.get_ocgs().items()}
        page = doc[0]
        if page.annots():
            for a in page.annots():
                obj = doc.xref_object(a.xref)
                m = re.search(r"/OC\s+(\d+)\s+0\s+R", obj)
                oc_xref = int(m.group(1)) if m else None
                oc_name = ocgs.get(oc_xref, None)
                print(f"{sub}/{os.path.basename(f):38s} | id={str(a.info.get(\"id\")):10s} | author={str(a.info.get(\"title\")):15s} | date={str(a.info.get(\"creationDate\")):24s} | OC={oc_name}")
'

